pub struct mplOrbitBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> mplOrbitBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_OBJECT_ID(&mut self, OBJECT_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(mplOrbit::VT_OBJECT_ID, OBJECT_ID);
    }

    #[inline]
    pub fn add_ELEMENTS(&mut self, ELEMENTS: ::flatbuffers::WIPOffset<mplElements<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<mplElements>>(mplOrbit::VT_ELEMENTS, ELEMENTS);
    }

    #[inline]
    pub fn add_STATE(&mut self, STATE: ::flatbuffers::WIPOffset<ephemerisDataLine<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<ephemerisDataLine>>(mplOrbit::VT_STATE, STATE);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> mplOrbitBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        mplOrbitBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<mplOrbit<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for mplOrbit<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("mplOrbit");
        ds.field("OBJECT_ID", &self.OBJECT_ID());
        ds.field("ELEMENTS", &self.ELEMENTS());
        ds.field("STATE", &self.STATE());
        ds.finish()
    }
}

