#[derive(Debug, Clone, PartialEq)]
pub struct mplOrbitT {
    pub OBJECT_ID: Option<alloc::string::String>,
    pub ELEMENTS: Option<alloc::boxed::Box<mplElementsT>>,
    pub STATE: Option<alloc::boxed::Box<ephemerisDataLineT>>,
}

impl Default for mplOrbitT {
    fn default() -> Self {
        Self {
            OBJECT_ID: None,
            ELEMENTS: None,
            STATE: None,
        }
    }
}

impl mplOrbitT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<mplOrbit<'b>> {
        let OBJECT_ID = self.OBJECT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ELEMENTS = self.ELEMENTS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATE = self.STATE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        mplOrbit::create(_fbb, &mplOrbitArgs{
            OBJECT_ID,
            ELEMENTS,
            STATE,
        })
    }
}

