    pub const VT_DELTA_MASS_KG: ::flatbuffers::VOffsetT = 22;
    pub const VT_REFERENCE_ORBIT: ::flatbuffers::VOffsetT = 24;
    pub const VT_ARC_INDEX: ::flatbuffers::VOffsetT = 26;
    pub const VT_MANEUVER_ID: ::flatbuffers::VOffsetT = 28;

