pub enum mplTrajectoryOffset {}

/// States sampled along an arc or a whole plan, column-major and parallel:
/// OFFSETS_S has one entry per sample and STATES has STATE_SIZE entries per
/// sample.
#[derive(Copy, Clone, PartialEq)]
pub struct mplTrajectory<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for mplTrajectory<'a> {
    type Inner = mplTrajectory<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> mplTrajectory<'a> {
    pub const VT_AXES: ::flatbuffers::VOffsetT = 4;
    pub const VT_STATE_SIZE: ::flatbuffers::VOffsetT = 6;
    pub const VT_OFFSETS_S: ::flatbuffers::VOffsetT = 8;
    pub const VT_STATES: ::flatbuffers::VOffsetT = 10;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        mplTrajectory { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplTrajectoryArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplTrajectory<'bldr>> {
        let mut builder = mplTrajectoryBuilder::new(_fbb);
        if let Some(x) = args.STATES { builder.add_STATES(x); }
        if let Some(x) = args.OFFSETS_S { builder.add_OFFSETS_S(x); }
        builder.add_STATE_SIZE(args.STATE_SIZE);
        builder.add_AXES(args.AXES);
        builder.finish()
    }

    pub fn unpack(&self) -> mplTrajectoryT {
        let AXES = self.AXES();
        let STATE_SIZE = self.STATE_SIZE();
        let OFFSETS_S = self.OFFSETS_S().map(|x| {
            x.into_iter().collect()
        });
        let STATES = self.STATES().map(|x| {
            x.into_iter().collect()
        });
        mplTrajectoryT {
            AXES,
            STATE_SIZE,
            OFFSETS_S,
            STATES,
        }
    }

    /// Axes and origin of STATES: Inertial = the plan's REFERENCE_FRAME about
    /// the central body; RIC or VNC = relative to the reference orbit (the
    /// target), centred on it.
    #[inline]
    pub fn AXES(&self) -> mplAxes {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<mplAxes>(mplTrajectory::VT_AXES, Some(mplAxes::Unspecified)).unwrap()}
    }

    /// Values per sample in STATES: 3 = position only, 6 = position and
    /// velocity. 0 is read as 6.
    #[inline]
    pub fn STATE_SIZE(&self) -> u8 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<u8>(mplTrajectory::VT_STATE_SIZE, Some(6)).unwrap()}
    }

    /// Seconds from the plan's start, one per sample, signed (negative for a
    /// track sampled backwards).
    #[inline]
    pub fn OFFSETS_S(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplTrajectory::VT_OFFSETS_S, None)}
    }

    /// Positions (km) and velocities (km/s), STATE_SIZE values per sample.
    #[inline]
    pub fn STATES(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplTrajectory::VT_STATES, None)}
    }
}

impl ::flatbuffers::Verifiable for mplTrajectory<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<mplAxes>("AXES", Self::VT_AXES, false)?
            .visit_field::<u8>("STATE_SIZE", Self::VT_STATE_SIZE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("OFFSETS_S", Self::VT_OFFSETS_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("STATES", Self::VT_STATES, false)?
            .finish();
        Ok(())
    }
}

