        let mut builder = mplArcBuilder::new(_fbb);
        builder.add_LAMBERT_Z(args.LAMBERT_Z);
        builder.add_DELTA_V_KM_S(args.DELTA_V_KM_S);
        builder.add_PERIOD_S(args.PERIOD_S);
