impl ::flatbuffers::Verifiable for mplArc<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("NAME", Self::VT_NAME, false)?
            .visit_field::<mplArcRole>("ROLE", Self::VT_ROLE, false)?
            .visit_field::<f64>("START_OFFSET_S", Self::VT_START_OFFSET_S, false)?
            .visit_field::<f64>("DURATION_S", Self::VT_DURATION_S, false)?
            .visit_field::<u32>("REVOLUTIONS", Self::VT_REVOLUTIONS, false)?
            .visit_field::<mplLambertBranch>("BRANCH", Self::VT_BRANCH, false)?
            .visit_field::<mplConic>("CONIC", Self::VT_CONIC, false)?
            .visit_field::<f64>("SEMI_MAJOR_AXIS_KM", Self::VT_SEMI_MAJOR_AXIS_KM, false)?
            .visit_field::<f64>("ECCENTRICITY", Self::VT_ECCENTRICITY, false)?
            .visit_field::<f64>("PERIAPSIS_RADIUS_KM", Self::VT_PERIAPSIS_RADIUS_KM, false)?
            .visit_field::<f64>("APOAPSIS_RADIUS_KM", Self::VT_APOAPSIS_RADIUS_KM, false)?
            .visit_field::<f64>("PERIOD_S", Self::VT_PERIOD_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>("START_STATE", Self::VT_START_STATE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>("END_STATE", Self::VT_END_STATE, false)?
            .visit_field::<mplAxes>("STATE_AXES", Self::VT_STATE_AXES, false)?
            .visit_field::<f64>("DELTA_V_KM_S", Self::VT_DELTA_V_KM_S, false)?
            .visit_field::<f64>("LAMBERT_Z", Self::VT_LAMBERT_Z, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplSolver>>("SOLVER", Self::VT_SOLVER, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplTrajectory>>("TRAJECTORY", Self::VT_TRAJECTORY, false)?
            .finish();
        Ok(())
    }
}

