impl ::flatbuffers::Verifiable for mplOption<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("NAME", Self::VT_NAME, false)?
            .visit_field::<bool>("SELECTED", Self::VT_SELECTED, false)?
            .visit_field::<u32>("REVOLUTIONS", Self::VT_REVOLUTIONS, false)?
            .visit_field::<mplLambertBranch>("BRANCH", Self::VT_BRANCH, false)?
            .visit_field::<mplPhasingDirection>("DIRECTION", Self::VT_DIRECTION, false)?
            .visit_field::<f64>("PHASE_ANGLE_DEG", Self::VT_PHASE_ANGLE_DEG, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("BURN_DELTA_V_KM_S", Self::VT_BURN_DELTA_V_KM_S, false)?
            .visit_field::<f64>("TOTAL_DELTA_V_KM_S", Self::VT_TOTAL_DELTA_V_KM_S, false)?
            .visit_field::<f64>("TOTAL_TIME_S", Self::VT_TOTAL_TIME_S, false)?
            .visit_field::<f64>("SEMI_MAJOR_AXIS_KM", Self::VT_SEMI_MAJOR_AXIS_KM, false)?
            .visit_field::<bool>("CLAMPED_TO_FLOOR", Self::VT_CLAMPED_TO_FLOOR, false)?
            .visit_field::<bool>("WITHIN_BUDGET", Self::VT_WITHIN_BUDGET, false)?
            .finish();
        Ok(())
    }
}

