pub enum mplLambertRequestOffset {}

/// Lambert problem (Lambert, LambertMinimumDeltaV). DEPARTURE and ARRIVAL
/// give the two positions; their velocities, when given, are the velocities
/// of the orbits being left and joined, and make the result's burns real
/// delta-v (LambertMinimumDeltaV requires them, since ranking needs a cost).
#[derive(Copy, Clone, PartialEq)]
pub struct mplLambertRequest<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for mplLambertRequest<'a> {
    type Inner = mplLambertRequest<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> mplLambertRequest<'a> {
    pub const VT_DEPARTURE: ::flatbuffers::VOffsetT = 4;
    pub const VT_ARRIVAL: ::flatbuffers::VOffsetT = 6;
    pub const VT_ENDPOINT_VELOCITIES: ::flatbuffers::VOffsetT = 8;
    pub const VT_TIME_OF_FLIGHT_S: ::flatbuffers::VOffsetT = 10;
    pub const VT_PROGRADE: ::flatbuffers::VOffsetT = 12;
    pub const VT_REVOLUTIONS: ::flatbuffers::VOffsetT = 14;
    pub const VT_BRANCH: ::flatbuffers::VOffsetT = 16;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        mplLambertRequest { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplLambertRequestArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplLambertRequest<'bldr>> {
        let mut builder = mplLambertRequestBuilder::new(_fbb);
        builder.add_TIME_OF_FLIGHT_S(args.TIME_OF_FLIGHT_S);
        builder.add_REVOLUTIONS(args.REVOLUTIONS);
        if let Some(x) = args.ARRIVAL { builder.add_ARRIVAL(x); }
        if let Some(x) = args.DEPARTURE { builder.add_DEPARTURE(x); }
        builder.add_BRANCH(args.BRANCH);
        builder.add_PROGRADE(args.PROGRADE);
        builder.add_ENDPOINT_VELOCITIES(args.ENDPOINT_VELOCITIES);
        builder.finish()
    }

    pub fn unpack(&self) -> mplLambertRequestT {
        let DEPARTURE = self.DEPARTURE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let ARRIVAL = self.ARRIVAL().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let ENDPOINT_VELOCITIES = self.ENDPOINT_VELOCITIES();
        let TIME_OF_FLIGHT_S = self.TIME_OF_FLIGHT_S();
        let PROGRADE = self.PROGRADE();
        let REVOLUTIONS = self.REVOLUTIONS();
        let BRANCH = self.BRANCH();
        mplLambertRequestT {
            DEPARTURE,
            ARRIVAL,
            ENDPOINT_VELOCITIES,
            TIME_OF_FLIGHT_S,
            PROGRADE,
            REVOLUTIONS,
            BRANCH,
        }
    }

    /// Departure position (and the departing orbit's velocity), inertial.
    #[inline]
    pub fn DEPARTURE(&self) -> Option<ephemerisDataLine<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>(mplLambertRequest::VT_DEPARTURE, None)}
    }

    /// Arrival position (and the arrival orbit's velocity), inertial.
    #[inline]
    pub fn ARRIVAL(&self) -> Option<ephemerisDataLine<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>(mplLambertRequest::VT_ARRIVAL, None)}
    }

    /// True when DEPARTURE and ARRIVAL carry orbit velocities; false = position
    /// only (the result then gives the transfer velocities, not delta-v).
    #[inline]
    pub fn ENDPOINT_VELOCITIES(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(mplLambertRequest::VT_ENDPOINT_VELOCITIES, Some(false)).unwrap()}
    }

    /// Time of flight, s.
    #[inline]
    pub fn TIME_OF_FLIGHT_S(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(mplLambertRequest::VT_TIME_OF_FLIGHT_S, Some(0.0)).unwrap()}
    }

    /// True for a prograde (short-way in the direction of motion) transfer.
    #[inline]
    pub fn PROGRADE(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(mplLambertRequest::VT_PROGRADE, Some(true)).unwrap()}
    }

    /// Revolution count of a Lambert problem; the largest count ranked by
    /// LambertMinimumDeltaV.
    #[inline]
    pub fn REVOLUTIONS(&self) -> u32 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<u32>(mplLambertRequest::VT_REVOLUTIONS, Some(0)).unwrap()}
    }

    /// Lambert: the arc to return when REVOLUTIONS >= 1 (Unspecified = Low).
    /// LambertMinimumDeltaV: narrows the ranking to one branch (Unspecified =
    /// rank both).
    #[inline]
    pub fn BRANCH(&self) -> mplLambertBranch {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<mplLambertBranch>(mplLambertRequest::VT_BRANCH, Some(mplLambertBranch::Unspecified)).unwrap()}
    }
}

impl ::flatbuffers::Verifiable for mplLambertRequest<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>("DEPARTURE", Self::VT_DEPARTURE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>("ARRIVAL", Self::VT_ARRIVAL, false)?
            .visit_field::<bool>("ENDPOINT_VELOCITIES", Self::VT_ENDPOINT_VELOCITIES, false)?
            .visit_field::<f64>("TIME_OF_FLIGHT_S", Self::VT_TIME_OF_FLIGHT_S, false)?
            .visit_field::<bool>("PROGRADE", Self::VT_PROGRADE, false)?
            .visit_field::<u32>("REVOLUTIONS", Self::VT_REVOLUTIONS, false)?
            .visit_field::<mplLambertBranch>("BRANCH", Self::VT_BRANCH, false)?
            .finish();
        Ok(())
    }
}

