    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplRelativeRequestArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplRelativeRequest<'bldr>> {
        let mut builder = mplRelativeRequestBuilder::new(_fbb);
        builder.add_CORRIDOR_HALF_WIDTH_KM(args.CORRIDOR_HALF_WIDTH_KM);
        builder.add_APPROACH_SPEED_KM_S(args.APPROACH_SPEED_KM_S);
        builder.add_MAX_DELTA_V_KM_S(args.MAX_DELTA_V_KM_S);
        builder.add_TIME_TO_CLOSEST_APPROACH_S(args.TIME_TO_CLOSEST_APPROACH_S);
        builder.add_MISS_DISTANCE_KM(args.MISS_DISTANCE_KM);
        builder.add_LEG_TIME_UPPER_ORBITS(args.LEG_TIME_UPPER_ORBITS);
        builder.add_LEG_TIME_LOWER_ORBITS(args.LEG_TIME_LOWER_ORBITS);
        builder.add_VELOCITY_TOLERANCE_KM_S(args.VELOCITY_TOLERANCE_KM_S);
        builder.add_POSITION_TOLERANCE_KM(args.POSITION_TOLERANCE_KM);
        builder.add_DURATION_S(args.DURATION_S);
        if let Some(x) = args.APPROACH_TARGET_KM { builder.add_APPROACH_TARGET_KM(x); }
        if let Some(x) = args.CONJUNCTION { builder.add_CONJUNCTION(x); }
        builder.add_SAMPLES_PER_LEG(args.SAMPLES_PER_LEG);
        builder.add_MAX_ITERATIONS(args.MAX_ITERATIONS);
        if let Some(x) = args.TARGET_VELOCITY_KM_S { builder.add_TARGET_VELOCITY_KM_S(x); }
        if let Some(x) = args.WAYPOINTS { builder.add_WAYPOINTS(x); }
        if let Some(x) = args.INITIAL_ROE { builder.add_INITIAL_ROE(x); }
        if let Some(x) = args.DRAG { builder.add_DRAG(x); }
        if let Some(x) = args.RELATIVE_STATE { builder.add_RELATIVE_STATE(x); }
        if let Some(x) = args.REFERENCE { builder.add_REFERENCE(x); }
        builder.add_APPROACH_AXIS(args.APPROACH_AXIS);
        builder.add_PREFER_RADIAL(args.PREFER_RADIAL);
        builder.add_HAS_MAX_DELTA_V(args.HAS_MAX_DELTA_V);
        builder.add_STM_DYNAMICS(args.STM_DYNAMICS);
        builder.add_DYNAMICS(args.DYNAMICS);
        builder.finish()
    }

    pub fn unpack(&self) -> mplRelativeRequestT {
        let REFERENCE = self.REFERENCE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let RELATIVE_STATE = self.RELATIVE_STATE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let DYNAMICS = self.DYNAMICS();
        let STM_DYNAMICS = self.STM_DYNAMICS();
        let DRAG = self.DRAG().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let DURATION_S = self.DURATION_S();
        let INITIAL_ROE = self.INITIAL_ROE().map(|x| {
            x.into_iter().collect()
        });
        let WAYPOINTS = self.WAYPOINTS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let TARGET_VELOCITY_KM_S = self.TARGET_VELOCITY_KM_S().map(|x| {
            x.into_iter().collect()
        });
        let MAX_ITERATIONS = self.MAX_ITERATIONS();
        let POSITION_TOLERANCE_KM = self.POSITION_TOLERANCE_KM();
        let VELOCITY_TOLERANCE_KM_S = self.VELOCITY_TOLERANCE_KM_S();
        let LEG_TIME_LOWER_ORBITS = self.LEG_TIME_LOWER_ORBITS();
        let LEG_TIME_UPPER_ORBITS = self.LEG_TIME_UPPER_ORBITS();
        let SAMPLES_PER_LEG = self.SAMPLES_PER_LEG();
        let MISS_DISTANCE_KM = self.MISS_DISTANCE_KM();
        let TIME_TO_CLOSEST_APPROACH_S = self.TIME_TO_CLOSEST_APPROACH_S();
        let MAX_DELTA_V_KM_S = self.MAX_DELTA_V_KM_S();
        let HAS_MAX_DELTA_V = self.HAS_MAX_DELTA_V();
        let PREFER_RADIAL = self.PREFER_RADIAL();
        let CONJUNCTION = self.CONJUNCTION().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let APPROACH_AXIS = self.APPROACH_AXIS();
        let APPROACH_TARGET_KM = self.APPROACH_TARGET_KM().map(|x| {
            x.into_iter().collect()
        });
        let APPROACH_SPEED_KM_S = self.APPROACH_SPEED_KM_S();
        let CORRIDOR_HALF_WIDTH_KM = self.CORRIDOR_HALF_WIDTH_KM();
        mplRelativeRequestT {
            REFERENCE,
            RELATIVE_STATE,
            DYNAMICS,
            STM_DYNAMICS,
            DRAG,
            DURATION_S,
            INITIAL_ROE,
            WAYPOINTS,
            TARGET_VELOCITY_KM_S,
            MAX_ITERATIONS,
            POSITION_TOLERANCE_KM,
            VELOCITY_TOLERANCE_KM_S,
            LEG_TIME_LOWER_ORBITS,
            LEG_TIME_UPPER_ORBITS,
            SAMPLES_PER_LEG,
            MISS_DISTANCE_KM,
            TIME_TO_CLOSEST_APPROACH_S,
            MAX_DELTA_V_KM_S,
            HAS_MAX_DELTA_V,
            PREFER_RADIAL,
            CONJUNCTION,
            APPROACH_AXIS,
            APPROACH_TARGET_KM,
            APPROACH_SPEED_KM_S,
            CORRIDOR_HALF_WIDTH_KM,
        }
    }

