impl ::flatbuffers::Verifiable for mplRelativeRequest<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplElements>>("REFERENCE", Self::VT_REFERENCE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ephemerisDataLine>>("RELATIVE_STATE", Self::VT_RELATIVE_STATE, false)?
            .visit_field::<mplRelativeDynamics>("DYNAMICS", Self::VT_DYNAMICS, false)?
            .visit_field::<mplRelativeDynamics>("STM_DYNAMICS", Self::VT_STM_DYNAMICS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplDifferentialDrag>>("DRAG", Self::VT_DRAG, false)?
            .visit_field::<f64>("DURATION_S", Self::VT_DURATION_S, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("INITIAL_ROE", Self::VT_INITIAL_ROE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<mplWaypoint>>>>("WAYPOINTS", Self::VT_WAYPOINTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("TARGET_VELOCITY_KM_S", Self::VT_TARGET_VELOCITY_KM_S, false)?
            .visit_field::<u32>("MAX_ITERATIONS", Self::VT_MAX_ITERATIONS, false)?
            .visit_field::<f64>("POSITION_TOLERANCE_KM", Self::VT_POSITION_TOLERANCE_KM, false)?
            .visit_field::<f64>("VELOCITY_TOLERANCE_KM_S", Self::VT_VELOCITY_TOLERANCE_KM_S, false)?
            .visit_field::<f64>("LEG_TIME_LOWER_ORBITS", Self::VT_LEG_TIME_LOWER_ORBITS, false)?
            .visit_field::<f64>("LEG_TIME_UPPER_ORBITS", Self::VT_LEG_TIME_UPPER_ORBITS, false)?
            .visit_field::<u32>("SAMPLES_PER_LEG", Self::VT_SAMPLES_PER_LEG, false)?
            .visit_field::<f64>("MISS_DISTANCE_KM", Self::VT_MISS_DISTANCE_KM, false)?
            .visit_field::<f64>("TIME_TO_CLOSEST_APPROACH_S", Self::VT_TIME_TO_CLOSEST_APPROACH_S, false)?
            .visit_field::<f64>("MAX_DELTA_V_KM_S", Self::VT_MAX_DELTA_V_KM_S, false)?
            .visit_field::<bool>("HAS_MAX_DELTA_V", Self::VT_HAS_MAX_DELTA_V, false)?
            .visit_field::<bool>("PREFER_RADIAL", Self::VT_PREFER_RADIAL, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<CDM>>("CONJUNCTION", Self::VT_CONJUNCTION, false)?
            .visit_field::<mplApproachAxis>("APPROACH_AXIS", Self::VT_APPROACH_AXIS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("APPROACH_TARGET_KM", Self::VT_APPROACH_TARGET_KM, false)?
            .visit_field::<f64>("APPROACH_SPEED_KM_S", Self::VT_APPROACH_SPEED_KM_S, false)?
            .visit_field::<f64>("CORRIDOR_HALF_WIDTH_KM", Self::VT_CORRIDOR_HALF_WIDTH_KM, false)?
            .finish();
        Ok(())
    }
}

