    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplRendezvousRequestArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplRendezvousRequest<'bldr>> {
        let mut builder = mplRendezvousRequestBuilder::new(_fbb);
        builder.add_TIME_STEP_S(args.TIME_STEP_S);
        builder.add_MAX_ACCELERATION_KM_S2(args.MAX_ACCELERATION_KM_S2);
        builder.add_KD_PER_S(args.KD_PER_S);
        builder.add_KP_PER_S2(args.KP_PER_S2);
        builder.add_DAMPING_RATIO(args.DAMPING_RATIO);
        builder.add_BANDWIDTH_RAD_S(args.BANDWIDTH_RAD_S);
        builder.add_HOLD_DURATION_S(args.HOLD_DURATION_S);
        builder.add_BRAKE_DURATION_S(args.BRAKE_DURATION_S);
        builder.add_DRIFT_DURATION_S(args.DRIFT_DURATION_S);
        builder.add_OUTPUT_EVERY(args.OUTPUT_EVERY);
        if let Some(x) = args.HOLD_POINT_KM { builder.add_HOLD_POINT_KM(x); }
        if let Some(x) = args.BRAKE_POINT_KM { builder.add_BRAKE_POINT_KM(x); }
        if let Some(x) = args.INITIAL_VELOCITY_KM_S { builder.add_INITIAL_VELOCITY_KM_S(x); }
        if let Some(x) = args.INITIAL_POSITION_KM { builder.add_INITIAL_POSITION_KM(x); }
        if let Some(x) = args.REFERENCE { builder.add_REFERENCE(x); }
        builder.add_INCLUDE_J2(args.INCLUDE_J2);
        builder.add_COMPENSATE_GRAVITY_GRADIENT(args.COMPENSATE_GRAVITY_GRADIENT);
        builder.add_COMPENSATE_CORIOLIS(args.COMPENSATE_CORIOLIS);
        builder.add_FEEDFORWARD(args.FEEDFORWARD);
        builder.add_HAS_KD(args.HAS_KD);
        builder.add_HAS_KP(args.HAS_KP);
        builder.add_HAS_DAMPING_RATIO(args.HAS_DAMPING_RATIO);
        builder.finish()
    }

