pub enum mplRelativeSolutionOffset {}

/// Relative-motion detail.
#[derive(Copy, Clone, PartialEq)]
pub struct mplRelativeSolution<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for mplRelativeSolution<'a> {
    type Inner = mplRelativeSolution<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> mplRelativeSolution<'a> {
    pub const VT_MODEL_REFERENCE: ::flatbuffers::VOffsetT = 4;
    pub const VT_DYNAMICS: ::flatbuffers::VOffsetT = 6;
    pub const VT_STM_DYNAMICS: ::flatbuffers::VOffsetT = 8;
    pub const VT_STATE_TRANSITION: ::flatbuffers::VOffsetT = 10;
    pub const VT_DRAG_COLUMNS: ::flatbuffers::VOffsetT = 12;
    pub const VT_DRAG_COLUMN_COUNT: ::flatbuffers::VOffsetT = 14;
    pub const VT_INITIAL_ROE: ::flatbuffers::VOffsetT = 16;
    pub const VT_PROPAGATED_ROE: ::flatbuffers::VOffsetT = 18;
    pub const VT_ACHIEVED_MISS_KM: ::flatbuffers::VOffsetT = 20;
    pub const VT_FEASIBLE: ::flatbuffers::VOffsetT = 22;
    pub const VT_CORRIDOR_DEVIATION_KM: ::flatbuffers::VOffsetT = 24;
    pub const VT_WITHIN_CORRIDOR: ::flatbuffers::VOffsetT = 26;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        mplRelativeSolution { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplRelativeSolutionArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplRelativeSolution<'bldr>> {
        let mut builder = mplRelativeSolutionBuilder::new(_fbb);
        builder.add_CORRIDOR_DEVIATION_KM(args.CORRIDOR_DEVIATION_KM);
        builder.add_ACHIEVED_MISS_KM(args.ACHIEVED_MISS_KM);
        if let Some(x) = args.PROPAGATED_ROE { builder.add_PROPAGATED_ROE(x); }
        if let Some(x) = args.INITIAL_ROE { builder.add_INITIAL_ROE(x); }
        if let Some(x) = args.DRAG_COLUMNS { builder.add_DRAG_COLUMNS(x); }
        if let Some(x) = args.STATE_TRANSITION { builder.add_STATE_TRANSITION(x); }
        if let Some(x) = args.MODEL_REFERENCE { builder.add_MODEL_REFERENCE(x); }
        builder.add_WITHIN_CORRIDOR(args.WITHIN_CORRIDOR);
        builder.add_FEASIBLE(args.FEASIBLE);
        builder.add_DRAG_COLUMN_COUNT(args.DRAG_COLUMN_COUNT);
        builder.add_STM_DYNAMICS(args.STM_DYNAMICS);
        builder.add_DYNAMICS(args.DYNAMICS);
        builder.finish()
    }

    pub fn unpack(&self) -> mplRelativeSolutionT {
        let MODEL_REFERENCE = self.MODEL_REFERENCE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let DYNAMICS = self.DYNAMICS();
        let STM_DYNAMICS = self.STM_DYNAMICS();
        let STATE_TRANSITION = self.STATE_TRANSITION().map(|x| {
            x.into_iter().collect()
        });
        let DRAG_COLUMNS = self.DRAG_COLUMNS().map(|x| {
            x.into_iter().collect()
        });
        let DRAG_COLUMN_COUNT = self.DRAG_COLUMN_COUNT();
        let INITIAL_ROE = self.INITIAL_ROE().map(|x| {
            x.into_iter().collect()
        });
        let PROPAGATED_ROE = self.PROPAGATED_ROE().map(|x| {
            x.into_iter().collect()
        });
        let ACHIEVED_MISS_KM = self.ACHIEVED_MISS_KM();
        let FEASIBLE = self.FEASIBLE();
        let CORRIDOR_DEVIATION_KM = self.CORRIDOR_DEVIATION_KM();
        let WITHIN_CORRIDOR = self.WITHIN_CORRIDOR();
        mplRelativeSolutionT {
            MODEL_REFERENCE,
            DYNAMICS,
            STM_DYNAMICS,
            STATE_TRANSITION,
            DRAG_COLUMNS,
            DRAG_COLUMN_COUNT,
            INITIAL_ROE,
            PROPAGATED_ROE,
            ACHIEVED_MISS_KM,
            FEASIBLE,
            CORRIDOR_DEVIATION_KM,
            WITHIN_CORRIDOR,
        }
    }

    /// Model reference, e.g. "Koenig-Guffanti-D'Amico ROE STM".
    #[inline]
    pub fn MODEL_REFERENCE(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(mplRelativeSolution::VT_MODEL_REFERENCE, None)}
    }

    /// Dynamics INITIAL_ROE was propagated with.
    #[inline]
    pub fn DYNAMICS(&self) -> mplRelativeDynamics {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<mplRelativeDynamics>(mplRelativeSolution::VT_DYNAMICS, Some(mplRelativeDynamics::Unspecified)).unwrap()}
    }

    /// Dynamics of STATE_TRANSITION and DRAG_COLUMNS.
    #[inline]
    pub fn STM_DYNAMICS(&self) -> mplRelativeDynamics {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<mplRelativeDynamics>(mplRelativeSolution::VT_STM_DYNAMICS, Some(mplRelativeDynamics::Unspecified)).unwrap()}
    }

    /// 6x6 relative-orbital-element state transition matrix over DURATION_S,
    /// row-major (36 values), dimensionless (the ROE are dimensionless).
    #[inline]
    pub fn STATE_TRANSITION(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplRelativeSolution::VT_STATE_TRANSITION, None)}
    }

    /// Drag sensitivity columns, row-major 6 x DRAG_COLUMN_COUNT: entry (i, k)
    /// is the change in ROE i at DURATION_S per unit of drag rate k, the rates
    /// being those of mplDifferentialDrag (1/s): k = 0 da-dot, 1 dex-dot, 2
    /// dey-dot. Unit: seconds (e.g. entry (0, 0) equals
    /// DURATION_S). J2DragEccentric gives one column (the da-dot column of the
    /// eccentric model), J2DragArbitrary three. Empty = no drag model.
    #[inline]
    pub fn DRAG_COLUMNS(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplRelativeSolution::VT_DRAG_COLUMNS, None)}
    }

    #[inline]
    pub fn DRAG_COLUMN_COUNT(&self) -> u8 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<u8>(mplRelativeSolution::VT_DRAG_COLUMN_COUNT, Some(0)).unwrap()}
    }

    /// Initial and propagated relative orbital elements (6 values each).
    #[inline]
    pub fn INITIAL_ROE(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplRelativeSolution::VT_INITIAL_ROE, None)}
    }

    #[inline]
    pub fn PROPAGATED_ROE(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(mplRelativeSolution::VT_PROPAGATED_ROE, None)}
    }

    /// CollisionAvoidance: miss distance the burn achieves, km.
    #[inline]
    pub fn ACHIEVED_MISS_KM(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(mplRelativeSolution::VT_ACHIEVED_MISS_KM, Some(0.0)).unwrap()}
    }

    /// CollisionAvoidance: true when the required miss is reachable within the
    /// available delta-v.
    #[inline]
    pub fn FEASIBLE(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(mplRelativeSolution::VT_FEASIBLE, Some(false)).unwrap()}
    }

    /// ApproachCorridor: largest lateral deviation from the corridor axis, km,
    /// and whether it stays within the corridor.
    #[inline]
    pub fn CORRIDOR_DEVIATION_KM(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(mplRelativeSolution::VT_CORRIDOR_DEVIATION_KM, Some(0.0)).unwrap()}
    }

    #[inline]
    pub fn WITHIN_CORRIDOR(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(mplRelativeSolution::VT_WITHIN_CORRIDOR, Some(false)).unwrap()}
    }
}

impl ::flatbuffers::Verifiable for mplRelativeSolution<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("MODEL_REFERENCE", Self::VT_MODEL_REFERENCE, false)?
            .visit_field::<mplRelativeDynamics>("DYNAMICS", Self::VT_DYNAMICS, false)?
            .visit_field::<mplRelativeDynamics>("STM_DYNAMICS", Self::VT_STM_DYNAMICS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("STATE_TRANSITION", Self::VT_STATE_TRANSITION, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("DRAG_COLUMNS", Self::VT_DRAG_COLUMNS, false)?
            .visit_field::<u8>("DRAG_COLUMN_COUNT", Self::VT_DRAG_COLUMN_COUNT, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("INITIAL_ROE", Self::VT_INITIAL_ROE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("PROPAGATED_ROE", Self::VT_PROPAGATED_ROE, false)?
            .visit_field::<f64>("ACHIEVED_MISS_KM", Self::VT_ACHIEVED_MISS_KM, false)?
            .visit_field::<bool>("FEASIBLE", Self::VT_FEASIBLE, false)?
            .visit_field::<f64>("CORRIDOR_DEVIATION_KM", Self::VT_CORRIDOR_DEVIATION_KM, false)?
            .visit_field::<bool>("WITHIN_CORRIDOR", Self::VT_WITHIN_CORRIDOR, false)?
            .finish();
        Ok(())
    }
}

