        ds.field("INITIAL_ROE", &self.INITIAL_ROE());
        ds.field("PROPAGATED_ROE", &self.PROPAGATED_ROE());
        ds.field("ACHIEVED_MISS_KM", &self.ACHIEVED_MISS_KM());
        ds.field("FEASIBLE", &self.FEASIBLE());
        ds.field("CORRIDOR_DEVIATION_KM", &self.CORRIDOR_DEVIATION_KM());
