    pub const VT_MAX_POSITION_ERROR_HOLD_KM: ::flatbuffers::VOffsetT = 32;
    pub const VT_FINAL_POSITION_ERROR_KM: ::flatbuffers::VOffsetT = 34;
    pub const VT_FINAL_VELOCITY_ERROR_KM_S: ::flatbuffers::VOffsetT = 36;
    pub const VT_SAMPLE_TIME_S: ::flatbuffers::VOffsetT = 38;
