    pub const VT_REFERENCE_ACCELERATION_KM_S2: ::flatbuffers::VOffsetT = 50;
    pub const VT_CONTROL_ACCELERATION_KM_S2: ::flatbuffers::VOffsetT = 52;
    pub const VT_POSITION_ERROR_KM: ::flatbuffers::VOffsetT = 54;
    pub const VT_VELOCITY_ERROR_KM_S: ::flatbuffers::VOffsetT = 56;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        mplRendezvousSolution { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args mplRendezvousSolutionArgs<'args>
    ) -> ::flatbuffers::WIPOffset<mplRendezvousSolution<'bldr>> {
        let mut builder = mplRendezvousSolutionBuilder::new(_fbb);
        builder.add_FINAL_VELOCITY_ERROR_KM_S(args.FINAL_VELOCITY_ERROR_KM_S);
        builder.add_FINAL_POSITION_ERROR_KM(args.FINAL_POSITION_ERROR_KM);
        builder.add_MAX_POSITION_ERROR_HOLD_KM(args.MAX_POSITION_ERROR_HOLD_KM);
        builder.add_MAX_POSITION_ERROR_BRAKE_KM(args.MAX_POSITION_ERROR_BRAKE_KM);
        builder.add_MAX_POSITION_ERROR_DRIFT_KM(args.MAX_POSITION_ERROR_DRIFT_KM);
        builder.add_RMS_POSITION_ERROR_KM(args.RMS_POSITION_ERROR_KM);
        builder.add_MAX_POSITION_ERROR_KM(args.MAX_POSITION_ERROR_KM);
        builder.add_MAX_CONTROL_ACCELERATION_KM_S2(args.MAX_CONTROL_ACCELERATION_KM_S2);
        builder.add_TOTAL_TIME_S(args.TOTAL_TIME_S);
        builder.add_BRAKE_END_S(args.BRAKE_END_S);
        builder.add_DRIFT_END_S(args.DRIFT_END_S);
        builder.add_MEAN_MOTION_RAD_S(args.MEAN_MOTION_RAD_S);
        if let Some(x) = args.VELOCITY_ERROR_KM_S { builder.add_VELOCITY_ERROR_KM_S(x); }
        if let Some(x) = args.POSITION_ERROR_KM { builder.add_POSITION_ERROR_KM(x); }
        if let Some(x) = args.CONTROL_ACCELERATION_KM_S2 { builder.add_CONTROL_ACCELERATION_KM_S2(x); }
        if let Some(x) = args.REFERENCE_ACCELERATION_KM_S2 { builder.add_REFERENCE_ACCELERATION_KM_S2(x); }
        if let Some(x) = args.REFERENCE_VELOCITY_KM_S { builder.add_REFERENCE_VELOCITY_KM_S(x); }
        if let Some(x) = args.REFERENCE_POSITION_KM { builder.add_REFERENCE_POSITION_KM(x); }
        if let Some(x) = args.VELOCITY_KM_S { builder.add_VELOCITY_KM_S(x); }
        if let Some(x) = args.POSITION_KM { builder.add_POSITION_KM(x); }
        if let Some(x) = args.SAMPLE_PHASE { builder.add_SAMPLE_PHASE(x); }
        if let Some(x) = args.SAMPLE_TIME_S { builder.add_SAMPLE_TIME_S(x); }
        builder.add_SATURATED_STEPS(args.SATURATED_STEPS);
        if let Some(x) = args.KD_PER_S { builder.add_KD_PER_S(x); }
        if let Some(x) = args.KP_PER_S2 { builder.add_KP_PER_S2(x); }
        if let Some(x) = args.INITIAL_VELOCITY_KM_S { builder.add_INITIAL_VELOCITY_KM_S(x); }
        if let Some(x) = args.MODEL_REFERENCE { builder.add_MODEL_REFERENCE(x); }
        builder.finish()
    }

