        let MAX_POSITION_ERROR_BRAKE_KM = self.MAX_POSITION_ERROR_BRAKE_KM();
        let MAX_POSITION_ERROR_HOLD_KM = self.MAX_POSITION_ERROR_HOLD_KM();
        let FINAL_POSITION_ERROR_KM = self.FINAL_POSITION_ERROR_KM();
