    pub const VT_ERROR_CODE: ::flatbuffers::VOffsetT = 24;
    pub const VT_ERROR_MESSAGE: ::flatbuffers::VOffsetT = 26;
    pub const VT_BURNS: ::flatbuffers::VOffsetT = 28;
    pub const VT_ARCS: ::flatbuffers::VOffsetT = 30;
    pub const VT_TOTAL_DELTA_V_KM_S: ::flatbuffers::VOffsetT = 32;
    pub const VT_TOTAL_TIME_S: ::flatbuffers::VOffsetT = 34;
    pub const VT_TOTAL_DELTA_MASS_KG: ::flatbuffers::VOffsetT = 36;
    pub const VT_SOLVER: ::flatbuffers::VOffsetT = 38;
    pub const VT_OPTIONS: ::flatbuffers::VOffsetT = 40;
    pub const VT_TRAJECTORY: ::flatbuffers::VOffsetT = 42;
    pub const VT_PHASING: ::flatbuffers::VOffsetT = 44;
    pub const VT_RELATIVE: ::flatbuffers::VOffsetT = 46;
    pub const VT_RENDEZVOUS: ::flatbuffers::VOffsetT = 48;
    pub const VT_GEOMETRY: ::flatbuffers::VOffsetT = 50;

