    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        MPL { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args MPLArgs<'args>
    ) -> ::flatbuffers::WIPOffset<MPL<'bldr>> {
        let mut builder = MPLBuilder::new(_fbb);
        builder.add_TOTAL_DELTA_MASS_KG(args.TOTAL_DELTA_MASS_KG);
        builder.add_TOTAL_TIME_S(args.TOTAL_TIME_S);
        builder.add_TOTAL_DELTA_V_KM_S(args.TOTAL_DELTA_V_KM_S);
        builder.add_PLAN_EPOCH_MS(args.PLAN_EPOCH_MS);
        builder.add_CREATED_AT_MS(args.CREATED_AT_MS);
        if let Some(x) = args.GEOMETRY { builder.add_GEOMETRY(x); }
        if let Some(x) = args.RENDEZVOUS { builder.add_RENDEZVOUS(x); }
        if let Some(x) = args.RELATIVE { builder.add_RELATIVE(x); }
        if let Some(x) = args.PHASING { builder.add_PHASING(x); }
        if let Some(x) = args.TRAJECTORY { builder.add_TRAJECTORY(x); }
        if let Some(x) = args.OPTIONS { builder.add_OPTIONS(x); }
        if let Some(x) = args.SOLVER { builder.add_SOLVER(x); }
        if let Some(x) = args.ARCS { builder.add_ARCS(x); }
        if let Some(x) = args.BURNS { builder.add_BURNS(x); }
        if let Some(x) = args.ERROR_MESSAGE { builder.add_ERROR_MESSAGE(x); }
        if let Some(x) = args.ERROR_CODE { builder.add_ERROR_CODE(x); }
        if let Some(x) = args.REQUEST { builder.add_REQUEST(x); }
        if let Some(x) = args.REFERENCE_FRAME { builder.add_REFERENCE_FRAME(x); }
        if let Some(x) = args.TARGET_OBJECT_ID { builder.add_TARGET_OBJECT_ID(x); }
        if let Some(x) = args.OBJECT_ID { builder.add_OBJECT_ID(x); }
        if let Some(x) = args.PLANNER { builder.add_PLANNER(x); }
        if let Some(x) = args.ID { builder.add_ID(x); }
        builder.add_STATUS(args.STATUS);
        builder.add_PROBLEM(args.PROBLEM);
        builder.finish()
    }

    pub fn unpack(&self) -> MPLT {
        let ID = self.ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS();
        let PLANNER = self.PLANNER().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let PROBLEM = self.PROBLEM();
        let PLAN_EPOCH_MS = self.PLAN_EPOCH_MS();
        let OBJECT_ID = self.OBJECT_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let TARGET_OBJECT_ID = self.TARGET_OBJECT_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let REFERENCE_FRAME = self.REFERENCE_FRAME().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let REQUEST = self.REQUEST().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let STATUS = self.STATUS();
        let ERROR_CODE = self.ERROR_CODE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let BURNS = self.BURNS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let ARCS = self.ARCS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let TOTAL_DELTA_V_KM_S = self.TOTAL_DELTA_V_KM_S();
        let TOTAL_TIME_S = self.TOTAL_TIME_S();
        let TOTAL_DELTA_MASS_KG = self.TOTAL_DELTA_MASS_KG();
        let SOLVER = self.SOLVER().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let OPTIONS = self.OPTIONS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let TRAJECTORY = self.TRAJECTORY().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let PHASING = self.PHASING().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let RELATIVE = self.RELATIVE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let RENDEZVOUS = self.RENDEZVOUS().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let GEOMETRY = self.GEOMETRY().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        MPLT {
            ID,
            CREATED_AT_MS,
            PLANNER,
            PROBLEM,
            PLAN_EPOCH_MS,
            OBJECT_ID,
            TARGET_OBJECT_ID,
            REFERENCE_FRAME,
            REQUEST,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            BURNS,
            ARCS,
            TOTAL_DELTA_V_KM_S,
            TOTAL_TIME_S,
            TOTAL_DELTA_MASS_KG,
            SOLVER,
            OPTIONS,
            TRAJECTORY,
            PHASING,
            RELATIVE,
            RENDEZVOUS,
            GEOMETRY,
        }
    }

