impl ::flatbuffers::Verifiable for MPL<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ID", Self::VT_ID, false)?
            .visit_field::<i64>("CREATED_AT_MS", Self::VT_CREATED_AT_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("PLANNER", Self::VT_PLANNER, false)?
            .visit_field::<mplProblem>("PROBLEM", Self::VT_PROBLEM, false)?
            .visit_field::<i64>("PLAN_EPOCH_MS", Self::VT_PLAN_EPOCH_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("OBJECT_ID", Self::VT_OBJECT_ID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("TARGET_OBJECT_ID", Self::VT_TARGET_OBJECT_ID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<RFM>>("REFERENCE_FRAME", Self::VT_REFERENCE_FRAME, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplRequest>>("REQUEST", Self::VT_REQUEST, false)?
            .visit_field::<mplStatus>("STATUS", Self::VT_STATUS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_CODE", Self::VT_ERROR_CODE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_MESSAGE", Self::VT_ERROR_MESSAGE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<mplBurn>>>>("BURNS", Self::VT_BURNS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<mplArc>>>>("ARCS", Self::VT_ARCS, false)?
            .visit_field::<f64>("TOTAL_DELTA_V_KM_S", Self::VT_TOTAL_DELTA_V_KM_S, false)?
            .visit_field::<f64>("TOTAL_TIME_S", Self::VT_TOTAL_TIME_S, false)?
            .visit_field::<f64>("TOTAL_DELTA_MASS_KG", Self::VT_TOTAL_DELTA_MASS_KG, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplSolver>>("SOLVER", Self::VT_SOLVER, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<mplOption>>>>("OPTIONS", Self::VT_OPTIONS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplTrajectory>>("TRAJECTORY", Self::VT_TRAJECTORY, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplPhasingSolution>>("PHASING", Self::VT_PHASING, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplRelativeSolution>>("RELATIVE", Self::VT_RELATIVE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplRendezvousSolution>>("RENDEZVOUS", Self::VT_RENDEZVOUS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<mplGeometrySolution>>("GEOMETRY", Self::VT_GEOMETRY, false)?
            .finish();
        Ok(())
    }
}

