impl MPLT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<MPL<'b>> {
        let ID = self.ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS;
        let PLANNER = self.PLANNER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROBLEM = self.PROBLEM;
        let PLAN_EPOCH_MS = self.PLAN_EPOCH_MS;
        let OBJECT_ID = self.OBJECT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let TARGET_OBJECT_ID = self.TARGET_OBJECT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let REFERENCE_FRAME = self.REFERENCE_FRAME.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let REQUEST = self.REQUEST.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATUS = self.STATUS;
        let ERROR_CODE = self.ERROR_CODE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let BURNS = self.BURNS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let ARCS = self.ARCS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let TOTAL_DELTA_V_KM_S = self.TOTAL_DELTA_V_KM_S;
        let TOTAL_TIME_S = self.TOTAL_TIME_S;
        let TOTAL_DELTA_MASS_KG = self.TOTAL_DELTA_MASS_KG;
        let SOLVER = self.SOLVER.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let OPTIONS = self.OPTIONS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let TRAJECTORY = self.TRAJECTORY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let PHASING = self.PHASING.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let RELATIVE = self.RELATIVE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let RENDEZVOUS = self.RENDEZVOUS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let GEOMETRY = self.GEOMETRY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        MPL::create(_fbb, &MPLArgs{
            ID,
            CREATED_AT_MS,
            PLANNER,
            PROBLEM,
            PLAN_EPOCH_MS,
            OBJECT_ID,
            TARGET_OBJECT_ID,
            REFERENCE_FRAME,
            REQUEST,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            BURNS,
            ARCS,
            TOTAL_DELTA_V_KM_S,
            TOTAL_TIME_S,
            TOTAL_DELTA_MASS_KG,
            SOLVER,
            OPTIONS,
            TRAJECTORY,
            PHASING,
            RELATIVE,
            RENDEZVOUS,
            GEOMETRY,
        })
    }
}

/// Verifies that a buffer of bytes contains a `MPL`
